import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Month 2021: Crimson Update","description":"","frontmatter":{"title":"Ceph Month 2021: Crimson Update","date":"2021-06-24T00:00:00.000Z","updated":"2021-06-25T00:00:00.000Z","tags":["Ceph","Crimson OSD","C","Store","Distributed Storage","Object Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Crimson_Update.md","filePath":"posts/2021/Ceph_Month_2021_-_Crimson_Update.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Month_2021_-_Crimson_Update.md"};function l(n,e,s,h,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph项目的会议重点讨论了两个关键进展：Crimson和C-Store。Crimson是一个新的OSD实现，旨在提高性能并减少CPU开销；C-Store是一个新的对象存储实现，旨在利用新兴存储技术如ZNS和持久内存。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Crimson OSD的进展</strong></p><ul><li>使用C-Star框架来减少上下文切换，提高多核环境下的性能。</li><li>专注于实现RBD工作负载、数据持久性和可靠性、可见性和调试以及稳定性。</li></ul></li><li><p><strong>C-Store的详细介绍</strong></p><ul><li>避免使用CPU密集型的元数据设计，如RocksDB，并利用ZNS和持久内存。</li><li>使用ZNS减少写放大和垃圾回收，利用持久内存作为数据和元数据的持久缓存。</li></ul></li><li><p><strong>C-Store的高级设计</strong></p><ul><li>包括根块、O节点索引、Omap树和逻辑地址到物理地址的映射。</li><li>使用逻辑地址映射简化垃圾回收和数据重定位。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续集中在稳定性和性能优化上。</li><li>未来工作将包括多核支持、克隆支持、直接突变支持和持久内存支持。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>推进Crimson OSD的稳定性测试和功能移植。</li><li>优化C-Store的垃圾回收机制和性能。</li><li>探索与NVMe over Fabric网关的潜在集成。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>SPDK将在C-Store之下作为底层I/O细节的插件。</li><li>Crimson OSD目前支持BlueStore，未来可能会有更多与NVMe over Fabric网关的协同工作。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了Crimson和C-Store在Ceph项目中的重要性，并明确了未来的开发方向和目标。</p>',13)])])}const C=a(r,[["render",l]]);export{u as __pageData,C as default};
